articles.body:
一。
在骑车去上早八的过程中，我提着装有续命咖啡的袋子，为了在车堆里正常蠕动而不被创到，（图示早八盛况）
我把袋子挂在了车把上，但此时袋子剧烈晃动，我突然灵机一动，用手拿袋子，竟然成功减小了晃动，于是我不禁陷入了沉思（文末的交互动画还是很有趣的）

先把袋子简化成单摆，其固有角频率为ω₀ = √(g/L)

骑行时，车把会不断进行微小的转向修正，如果激励频率接近袋子的固有频率，就可能发生共振，使摆动不断放大。

但换成手提，改变的其实不只是阻尼。肩、肘、腕组成的柔性系统让手不必完全跟随车把运动，相当于改变了悬挂点的加速度输入。

再从能量角度来看，对于小角度摆动，能量变化率 ≈ 悬挂点输入功率 − 阻尼耗散功率，第二项是阻尼耗能，而第一项可以为正也可以为负，取决于悬挂点加速度与摆动速度的相位关系。

也就是说，手适当地运动，反而可能主动减少袋子的摆动能量。相关人体运动控制研究也发现，人在携带物体时会提前协调肌肉活动，而不是等物体晃动后才作出反应。

所以人体确实具有减振能力，但这个现象究竟是隔振、避开共振，还是主动控制占主导，光凭肉眼观察其实还无法确定。之后可以记录一下两种状态下悬挂点的运动，看看究竟是哪一部分起了主要作用。

二。c++

实际任务：统计销量，按“日均销量×备货天数”估算需求，再扣除库存。
 为复习本章，保留原生数组、指针、new/delete，不引入容器或类。
 样例价格单位为元；预测仅采用近期均值，未考虑节假日和安全库存。
#include <iostream>
#include <iomanip>  // setw限制单词输入长度，fixed、setprecision设置小数格式
#include <cstring>  // strcmp比较字符串内容，而不是地址
#include <cstddef>  // size_t表示大小，ptrdiff_t表示数组元素指针之差
#include <cstdint>  // 本机支持的uintptr_t，可显示指针转换后的整数值
#include <limits>
#include <cctype>
#include <new>      // nothrow使下面基本类型的内存分配失败返回nullptr
using namespace std;
//  数组是一组同类型元素，固定数组的长度必须是常量表达式。
// const int和#define都能给出常量长度；下标是整型表达式，从0开始。
const int PRODUCTS = 4, DAYS = 3, TEXT_SIZE = 80;
const char NAMES[][12] = {"book", "pen", "bag", "eraser"}; // 二维字符数组
const double PRICE[PRODUCTS] = {12.50, 2.00, 18.00, 1.50}; // 完整初始化
const int STOCK[PRODUCTS] = {8, 12}; // 部分初始化，剩余两格自动补0
const int SALES[DAYS][PRODUCTS] = {{5,12,2,8}, {7,15,1,6}, {6,9,3,7}};
// SALES[day][item]，一行是一天，一列是一种商品，按行连续存放。
// 统一清理本行，返回“后面是否只有空白”，避免重复校验代码。
bool finishLine() {
    bool clean = true;
    char ch;
    while (cin.get(ch) && ch != '\n')
        if (!isspace(static_cast<unsigned char>(ch))) clean = false;
    return clean;
}
// 数值数组必须逐个输入。result接收地址，*result修改调用者的变量。
// 范围检查防止非法天数和销量，一行只接受一个整数，拒绝12abc、1.5等。
bool readInteger(const char* prompt, int low, int high, int* result) {
    while (true) {
        cout << prompt;
        long long value;
        if (!(cin >> value)) {
            if (cin.eof() || cin.bad()) return false;
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            cout << "请输入一个整数。\n";
            continue;
        }
        if (finishLine() && value >= low && value <= high) {
            *result = static_cast<int>(value);
            return true;
        }
        cout << "每行一个整数，范围：" << low << " ~ " << high << "。\n";
    }
}
// 字符数组可以整体输入，>>遇空白结束，并补'\0'。
// char[16]配setw(16)最多存15字节，最后一格留给结束标志。
bool readProduct(int* item) {
    while (true) {
        char sku[16] = {};
        cout << "商品名（book / pen / bag / eraser）：";
        if (!(cin >> setw(16) >> sku)) return false;
        const bool clean = finishLine();
        for (int i = 0; clean && i < PRODUCTS; ++i)
            if (strcmp(sku, NAMES[i]) == 0) { *item = i; return true; }
        cout << "商品名无效，请重新输入。\n";
    }
}
// getline能保留空格，并限制容量，不用不安全的旧gets函数。
bool readRemark(char* text) {
    while (true) {
        cout << "订单备注（可含空格，最多79字节）：";
        if (cin.getline(text, TEXT_SIZE)) return true;
        if (cin.eof() || cin.bad()) return false;
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cout << "备注过长，请重新输入。\n";
    }
}
// 在有效C字符串上数到'\0'为止，不包括结束标志。
// 返回字节数，不能把UTF-8中文的一个字节当成一个汉字。
size_t textLength(const char* text) {
    const char* p = text;
    while (*p != '\0') ++p;
    return static_cast<size_t>(p - text);
}
// 复制和连接都先检查容量，且要求源、目标互不重叠。
bool copyText(char* to, size_t capacity, const char* from) {
    if (textLength(from) >= capacity) return false;
    while (*from != '\0') { *to = *from; ++to; ++from; }
    *to = '\0';
    return true;
}
//  找到原字符串结尾，再追加字符和新的'\0'。
bool appendText(char* to, size_t capacity, const char* from) {
    size_t used = 0;
    while (used < capacity && to[used] != '\0') ++used;
    if (used == capacity || textLength(from) >= capacity - used) return false;
    return copyText(to + used, capacity - used, from);
}
// 方法1下标左移。删除后i不动，继续检查刚移到当前位置的字符。
// 每次移动时连'\0'一起移，连续的###才不会漏删。最坏O(n²)。
void removeByIndexShift(char* s, char target) {
    for (int i = 0; s[i] != '\0'; ) {
        if (s[i] != target) { ++i; continue; }
        for (int j = i; s[j] != '\0'; ++j) s[j] = s[j + 1];
    }
}
// 方法2 指针左移；p找目标，q把后续字符逐个往前搬。
void removeByPointerShift(char* s, char target) {
    for (char* p = s; *p != '\0'; ) {
        if (*p != target) { ++p; continue; }
        for (char* q = p; *q != '\0'; ++q) *q = *(q + 1);
    }
}
// 方法3 双指针压缩。read总前进，write只在保留字符时前进。
// write不超过read，不覆盖未读数据,只扫描一遍，O(n)。业务优先用这种。
void removeByPointerCompact(char* s, char target) {
    char* write = s;
    for (const char* read = s; *read != '\0'; ++read) {
        if (*read == target) continue;
        *write = *read;
        ++write;
    }
    *write = '\0'; // 新结尾必须补结束标志，否则会输出旧的尾部字符
}
//方法4双下标压缩，与方法3等价，便于对照a[i]与*(a+i)。
void removeByIndexCompact(char* s, char target) {
    int write = 0;
    for (int read = 0; s[read] != '\0'; ++read) {
        if (s[read] == target) continue;
        s[write] = s[read];
        ++write;
    }
    s[write] = '\0';
}
void printOrderTitle(int item, const char* raw) {
    char remarks[4][TEXT_SIZE] = {}, title[128] = {};
    for (int i = 0; i < 4; ++i)
        if (!copyText(remarks[i], sizeof(remarks[i]), raw)) return;
    removeByIndexShift(remarks[0], '#');
    removeByPointerShift(remarks[1], '#');
    removeByPointerCompact(remarks[2], '#');
    removeByIndexCompact(remarks[3], '#');
    bool same = true;
    for (int i = 1; i < 4; ++i)
        if (strcmp(remarks[0], remarks[i]) != 0) same = false;
    if (!appendText(title, sizeof(title), NAMES[item]) ||
        !appendText(title, sizeof(title), " / ") ||
        !appendText(title, sizeof(title), remarks[2])) return;
    int countE = 0; // 逐字符统计小写e；'e'与'E'不同
    for (const char* p = remarks[2]; *p != '\0'; ++p)
        if (*p == 'e') ++countE;
    cout << "原备注：" << raw << "\n清理后：" << remarks[2]
              << "\n清理后字节数：" << textLength(remarks[2]) << "\n小写e个数：" << countE
              << "\n四种删除方法结果：" << (same ? "一致" : "不一致")
              << "\n订单标题：" << title << '\n';
}
// 同一流程处理样例和自定义矩阵，避免重复报表代码。
bool report(bool input = false) {
    int sales[DAYS][PRODUCTS] = {}, dayTotals[DAYS] = {}, productTotals[PRODUCTS] = {};
    for (int day = 0; day < DAYS; ++day)
        for (int item = 0; item < PRODUCTS; ++item) {
            sales[day][item] = SALES[day][item];
            if (!input) continue;
            cout << "第" << day + 1 << "天，" << NAMES[item] << "：\n";
            if (!readInteger("销量（0~100000）：", 0, 100000, &sales[day][item])) return false;
        }
    // row是“指向一行的指针”：+1跨过PRODUCTS个int；它不是int**。
    const int (*row)[PRODUCTS] = sales;
    cout << "\n【历史销量报表】\n日期       book    pen    bag eraser   当日合计\n";
    for (int day = 0; day < DAYS; ++day, ++row) {
        cout << "第" << day + 1 << "天  ";
        for (int item = 0; item < PRODUCTS; ++item) {
            const int value = *(*row + item); // 等价于sales[day][item]
            dayTotals[day] += value;
            productTotals[item] += value;
            cout << setw(7) << value;
        }
        cout << setw(11) << dayTotals[day] << '\n';
    }
    int total = 0;
    const int* peak = dayTotals;
    for (const int* p = dayTotals; p != dayTotals + DAYS; ++p) {
        total += *p;
        if (*p > *peak) peak = p; // 保存最大值地址，相同值取最早一天
    }
    cout << "三天总销量：" << total << " 件\n平均每天："
              << static_cast<double>(total) / DAYS << " 件\n销量最高：第"
              << peak - dayTotals + 1 << "天，" << *peak << " 件\n各商品合计：";
    for (int i = 0; i < PRODUCTS; ++i) cout << NAMES[i] << '=' << productTotals[i] << "  ";
    //  指针数组：每格存一个地址。选择排序只交换地址，不搬动字符串。
    const char* names[PRODUCTS] = {NAMES[0], NAMES[1], NAMES[2], NAMES[3]};
    for (int i = 0; i < PRODUCTS - 1; ++i) {
        int k = i;
        for (int j = i + 1; j < PRODUCTS; ++j)
            if (strcmp(names[j], names[k]) < 0) k = j;
        const char* temp = names[k]; names[k] = names[i]; names[i] = temp;
    }
    cout << "\n商品名按字典序：";
    for (int i = 0; i < PRODUCTS; ++i) cout << names[i] << (i == PRODUCTS - 1 ? "\n" : "  ");
    return true;
}
// 输入 → 动态数组 → 统计 → 补货 → 释放，构成业务主线。
bool runPurchase(bool sample) {
    int item = 0, n = DAYS, coverDays = 2;
    char remark[TEXT_SIZE] = "week##end #sale";
    if (!sample && (!readProduct(&item) ||
        !readInteger("历史天数（1~366）：", 1, 366, &n) ||
        !readInteger("备货天数（1~365）：", 1, 365, &coverDays) || !readRemark(remark))) {
        cout << "输入已结束，取消本次计算。\n";
        return false;
    }
    // n运行时确定，因此用new[],不能写标准C++不支持的int daily[n]。
    // 普通new失败抛bad_alloc,显式用nothrow才能这样检查nullptr。
    int* daily = new (nothrow) int[n](); // ()把所有元素初始化为0
    if (daily == nullptr) { cout << "内存分配失败。\n"; return false; }
    bool complete = true;
    for (int i = 0; i < n; ++i) {
        if (sample) daily[i] = SALES[i][item];
        else {
            cout << "第" << i + 1 << "天：\n";
            // daily+i就是&daily[i],被调用函数通过*result写入这一格。
            if (!readInteger("销量（0~100000）：", 0, 100000, daily + i)) { complete = false; break; }
        }
    }
    if (complete) {
        long long total = 0; // 普通统计量用局部变量，无需各自申请堆内存
        const int* peak = daily;
        for (const int* p = daily; p != daily + n; ++p) {
            total += *p;
            if (*p > *peak) peak = p;
        }
        // 不能先做整数total/n,用(a+b-1)/b对非负整数比例向上取整。
        // 已限制n、销量和天数，long long乘积及最终int结果均不会溢出。
        const int required = static_cast<int>((total * coverDays + n - 1) / n);
        const int purchase = required > STOCK[item] ? required - STOCK[item] : 0;
        const double* price = &PRICE[item]; // 合法double指针，所指类型必须匹配
        cout << "\n【补货建议】\n商品：" << NAMES[item]
                  << "\n历史天数：" << n << "\n历史总销量：" << total << " 件\n日均销量："
                  << static_cast<double>(total) / n << " 件\n最高日销量：" << *peak
                  << " 件（第" << peak - daily + 1 << "天）\n未来备货天数：" << coverDays
                  << "\n预计需求：" << required << " 件\n现有库存：" << STOCK[item]
                  << " 件\n建议补货：" << purchase << " 件\n采购单价：" << *price
                  << " 元\n预计采购金额：" << purchase * (*price) << " 元\n";
        printOrderTitle(item, remark);
    } else cout << "输入已结束，取消本次计算。\n";
    // daily始终保存申请首地址，遍历改用p；弄丢首地址会导致内存泄漏。
    delete[] daily; // new[]配delete[]；输入中断也走到这里，释放已申请空间
    daily = nullptr; // delete不会自动清空指针，释放后绝不能再解引用
    // 若另有别名指针，它不会自动变空。对旧地址重复delete是错误的。
    return complete;
}
// 业务已覆盖的知识点不再重复造数据,等价写法直接写在注释中。
void reviewSyntax() {
    cout << "\n【数组与指针语法复习】\n";
    // 一维三种：int a[3]={1,2,3}; int b[]={1,2,3}; int c[3]={1};
    // 二维五种（均为2×3），依次为按行、顺序、部分、推导首维、按行推导。
    // int m1[2][3]={{1,3,5},{7,8,9}},int m2[2][3]={1,3,5,7,8,9};
    // int m3[2][3]={{1},{7,8}}; int m4[][3]={3,5,7,9}; int m5[][3]={{3},{5,7,9}};
    // m3的两行为{1,0,0}、{7,8,0}；m4第二行为{9,0,0}，不能省略列数。
    // 字符数组四种写法都包含'\0'：
    // char c1[6]={'t','o','t','a','l','\0'}; char c2[6]="total";
    // char c3[]={"total"}; char c4[]="total";
    char word[] = "total", padded[8] = "pen";
    cout << "字符串容量=" << sizeof(word) << "，长度=" << textLength(word)
              << "，剩余空间补零=" << (padded[7] == '\0') << '\n';
    // 二维字符数组的四种写法，行容量都是5，多余字符位置补'\0'：
    // char s1[3][5]={{'b','o','o','k','\0'},{'p','e','n','\0'},{'b','a','g','\0'}};
    // char s2[3][5]={"book","pen","bag"}; char s3[][5]={"book","pen","bag"};
    // char s4[][5]={{"book"},{"pen"},{"bag"}};
    // char bad[6]="program"; 错,7个字母加结束标志至少8格。
    // char raw[3]={'p','e','n'}可作为字符数组，但不是可整体输出的C字符串。
    // 类型决定含义；&取地址，*访问该地址的对象。
    int a = 65, b = 0;
    char letter = 'A'; // 本机ASCII编码中A为65，char输出显示字母
    cout << "类型与输出：" << a << ' ' << letter << ' ' << int(letter) << '\n';
    int* p1 = &a;
    int* p2 = p1; // 复制地址，两个指针共同访问a，不会复制a对象
    *p1 = 20;
    cout << "通过别名读取a：" << *p2 << '\n';
    p1 = &b; *p1 = 200; // 改指针自身的地址后，解引用改为访问b
    cout << "重新指向：a=" << a << "，b=" << b << "，a地址=" << p2
              << "，十进制地址表示=" << dec << reinterpret_cast<uintptr_t>(p2) << '\n';
    // uintptr_t为可选标准类型，常见桌面编译器支持,地址每次运行可能不同。
    // int* bad; *bad=1; 错：尚未指向合法对象。double* bad=&a; 错,类型不匹配。
    // p1=300或p1=a错误,(int*)300强转也不会创造有效int对象。
    // int* p,q, 只有p是指针，q是int；不要因星号位置误判。
    //下标等价于解引用偏移；指针±整数按元素数移动。
    int values[] = {1,2,3,4,5};
    int* cursor = values + 1;
    const ptrdiff_t distance = &values[3] - cursor;
    cout << "下标等价：" << values[2] << '=' << *(values + 2)
              << "，cursor[2]=" << cursor[2] << "，指针相差元素数=" << distance << '\n';
    ++cursor; --cursor; cursor = cursor + 2; cursor = cursor - 1;
    cout << "移动后元素=" << *cursor << "，数组字节数=" << sizeof(values)
              << "，指针字节数=" << sizeof(cursor)
              << "，元素个数=" << sizeof(values) / sizeof(values[0]) << '\n';
    // 差值类型是ptrdiff_t，不一定是int,相减须在同一数组，不能只要求同类型。
    // values+5是合法尾后指针，可比较而不可解引用,values[5]越界。
    // 数组名通常转换成首元素指针，但数组不是指针变量，values++和values=cursor非法。
    // 指针不能相加、相乘或相除。形参int a[]实际调整成int*，sizeof不能恢复原数组长度。
    // 分开计算，清楚区分“指针移动”和“元素加1”，避免混在一条输出里。
    int trial[] = {10,20,30,40};
    int* p = trial;
    int r1 = *++p;   // *(++p)先移到第2格，再取20
    int r2 = *p++;   // *(p++)先取20，再移到第3格
    int r3 = ++*p;   // ++(*p)第3格30变31，取新值31，p不动
    int r4 = (*p)++; // 先取旧值31，再把第3格变32，p不动
    cout << "五个指针表达式：" << r1 << ' ' << r2 << ' ' << r3 << ' ' << r4 << ' ' << *p << '\n';
    // 可写数组用char*,字面量用const char*，不可修改其内容。
    char editable[] = "Hello world!";
    char* ps = editable;
    const char* literal = "I am a string";
    cout << "字符指针：" << ps << "，首字符=" << *ps << "，后缀=" << literal + 5
              << "，地址=" << static_cast<const void*>(ps) << '\n';
    // cout<<char*按字符串输出直到'\0',转成void*才按地址输出。
    const int (*row)[PRODUCTS] = SALES; // 数组指针：指向一整行
    const int* pointers[] = {SALES[0], SALES[1]}; // 指针数组,每格是一个指针
    cout << "二维三种访问：" << SALES[1][2] << ' ' << *(SALES[1] + 2)
              << ' ' << *(*(SALES + 1) + 2) << "，行指针=" << row[1][2]
              << "，指针数组=" << pointers[1][2] << '\n';
    // SALES转换后指向首行，SALES[i]转换后指向该行首元素，SALES[i][j]才是整数。
    // 不要用一个int*跨行遍历整个二维数组，应逐行处理或使用行指针。
    // 
    
    单对象与数组分别练习一次，避免业务中为普通统计量反复申请堆内存。
    int* single = new (nothrow) int(5); // 有初值；new int则需先赋值再读取
    if (single) { cout << "动态单对象：" << *single << '\n'; delete single; }
    single = nullptr; // 普通局部对象在执行到声明时创建，并非全部在运行前分配
    int* initialized = new (nothrow) int[3]{1,2,3}; // C++11起允许列表初始化
    if (initialized) {
        cout << "动态数组列表初始化：" << initialized[0] << ' ' << initialized[1] << ' ' << initialized[2] << '\n';
        delete[] initialized; // new配delete，new[]配delete[]，不能混用
    }
    initialized = nullptr;
    delete[] initialized; // 删除空指针安全；不是对刚才的旧地址再次释放
}
