一。c++

这个程序解决一个具体问题，记录连续几天的开销，判断是否超出总预算，找出花费最多的类别与日期。

#include <iostream>
#include <iomanip>
#include <new>  //<new> 提供这里使用的nothrow
using namespace std;


int main() 
    {
    constexpr int MAX_DAYS = 31, COLS = 3;//constexpr 在这里表示这是编译时就能确定的常量
    //MAX_DAYS 表示最多记录31天。COLS 是列数，表示这里有三类支出
    constexpr long long MAX_BUDGET = 1000000000000LL;
    //long long 是一种整数类型，通常能保存比 int 更大的整数。预算和累计金额可能比较大，所以用它。
    char title[64]{}; // [易错] 字符串必须给 '\0' 留空间。
    const char* category[COLS] = {"餐饮", "交通", "其他"};
    // [易错] 字符串字面量用 const char*，不能修改内容。
    cout << "账本名称（可以含空格，最多63字节）：\n";
    if (!cin.getline(title, sizeof title)) //如果读取失败，就执行大括号里的代码。
    {
        cerr << "名称过长或读取失败。\n";//cerr 用于输出错误信息。
        return 1;
    }
    // cin >> title 遇空格结束；getline 可以读取整行。
    int days;
    long long budget;
    cout << "输入天数（1~31）和总预算（整数分）：\n";
    if (!(cin >> days >> budget) || days < 1 || days > MAX_DAYS ||
        budget < 0 || budget > MAX_BUDGET) 
    //整个 if 检查五种情况读取失败或者 days < 1或者 days > 31或者 budget < 0或者 budget 超出上限
    //|| 会从左到右检查，一旦某一项成立，后面就不再检查。
    {
        cerr << "天数或预算无效。\n";
        return 1;
    }


    int (*const expense)[COLS] = new (nothrow) int[days][COLS]{};
    //右边表示在程序运行时，申请一个 days 行、3列的二维整数数组，并把所有元素初始化为0。
    //int (*expense)[3]指向一行3个int的指针
    //int(*const expense)[3]在此基础上，指针本身不能改
    //int (*p)[3]一个指针，指向含3个int的数组   (()的重要性）
    //int*p[3];一个数组，里面有3个int指针
    // [易错] (*expense)[COLS] 是行指针；*rank[] 是指针数组。
    // [易错] {} 清零；nothrow 失败返回 nullptr；const 锁住首地址。
    if (!expense) //如果没有获得有效地址，就报错退出。
    { 
       cerr << "内存不足。\n"; return 1; 
    }
    long long daily[MAX_DAYS]{}, byCategory[COLS]{};//{} 将所有金额初始化为0。
    const long long* rank[MAX_DAYS]{};
    cout << "每天一行，依次输入餐饮、交通、其他（整数分）：\n";
    for (int d = 0; d < days; ++d)
        for (int c = 0; c < COLS; ++c)
            if (!(cin >> expense[d][c]) || expense[d][c] < 0 ||
                expense[d][c] > 100000000) {
                cerr << "输入无效：每项须为0~100000000整数分。\n";
                delete[] expense;
                return 1;
            }


    long long total = 0;
    const int (*row)[COLS] = expense;
    for (int d = 0; d < days; ++d, ++row) 
    {
        long long& today = daily[d]; // 引用是原元素的别名，不是副本。
        for (int c = 0; c < COLS; ++c) 
        {
            today += *(*row + c); // 等价于 expense[d][c]。
    //row → 指向当前这一行
    //*row → 当前这一行数组
    //*row + c→ 这一行第c个元素的地址
    //*(*row + c)→ 取出该地址上的金额
            byCategory[c] += (*row)[c];
        }
    //for (初始化; 继续执行的条件; 每次执行后的操作)
    //外层的 d 控制日期，内层的 c 控制类别
    // int (*const expense)[3]地址不能改，但可以通过它修改金额
    //const int (*row)[3]地址可以改，但不能通过它修改金额 
                rank[d] = &today; // & 取地址，* 解引用。
        total += today;
    }
    // [易错] row++ 前进一整行；row的类型决定步长。


    // 冒泡排序“地址”：账本仍按日期排列，排行榜按金额排列。
    for (int i = 0; i < days - 1; ++i)
        for (int j = 0; j < days - 1 - i; ++j)
            if (*rank[j] < *rank[j + 1]) {
                const long long* temp = rank[j];
                rank[j] = rank[j + 1];
                rank[j + 1] = temp;
            }
    // [易错] j+1必须有效；比较金额 *rank[j]，不要比较地址。
    // [易错] const long long* 禁止通过它改金额，指针本身可交换。


    int biggest = 0;
    for (int c = 1; c < COLS; ++c)
        if (byCategory[c] > byCategory[biggest]) biggest = c;
    cout << fixed << setprecision(2) << "\n【" << title << "】\n";
    cout << "总支出：" << total / 100.0 << " 元\n";
    cout << "日均支出：" << total / 100.0 / days << " 元\n";
    // [易错] 不写 total / days / 100：整数除法会丢失小数。
    cout << (total > budget ? "超出预算：" : "剩余预算：")
         << (total > budget ? total - budget : budget - total) / 100.0
         << " 元\n";
    for (int c = 0; c < COLS; ++c)
        cout << category[c] << "：" << byCategory[c] / 100.0 << " 元\n";
    if (total > 0)
        cout << "优先检查【" << category[biggest] << "】的明细。\n";
    cout << "每日支出排名（同额按日期先后）：\n";
    for (int i = 0; i < days; ++i)
        cout << "第" << rank[i] - daily + 1 << "天："
             << *rank[i] / 100.0 << " 元\n";
    // [易错] 同一数组内指针相减得到元素间距；末尾后一位不可解引用。
    delete[] expense; // [易错] new[] 配 delete[]，只释放一次。
    // rank 指向局部数组 daily，不拥有内存，不应 delete rank[i]。
    return 0;
}


